"""Commands added so the product works over the CLI and web app (generated by _tools/add_commands.py)."""

import contextlib
import io
import json
import pathlib
import tempfile
import unittest

from likeness_license.__main__ import main

EX = pathlib.Path(__file__).resolve().parent.parent / "examples"


class CommandTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, obj) -> str:
        path = pathlib.Path(self.tmp.name) / "req.json"
        path.write_text(json.dumps(obj), encoding="utf-8")
        return str(path)

    def run_cli(self, argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = main(argv)
        self.assertIn(code, (0, 1), out.getvalue())
        return json.loads(out.getvalue())

    def test_permitted_use_is_priced(self):
        out = self.run_cli(["check", str(EX / "licence-request.json")])
        self.assertTrue(out["allowed"])
        self.assertAlmostEqual(out["fee"], round(3000 * 180 / 365, 2))

    def test_prohibited_purpose_is_refused(self):
        req = json.loads((EX / "licence-request.json").read_text(encoding="utf-8"))
        req["request"]["purpose_tags"] = ["Political"]
        out = self.run_cli(["check", self.write(req)])
        self.assertFalse(out["allowed"])


if __name__ == "__main__":
    unittest.main()
